  'use strict';
  const chunkSet = {"title":"Spelling Patterns","topic":"Vocabulary / Word Study","questions":[{"id":"vocabulary-spelling-patterns-q0101","version":3,"contentHash":"sha256:1e13172bcc00ac9331abe6886738a7c147e1399931d85e1cdfd240f574a092ac","question":"Grade 4 Easy: Choose the best answer. How many syllables are in computer?","choices":["two","one","three","four"],"correct":2,"studyAid":{"definition":"A syllable is a single, unbroken sound of a spoken word. Every syllable must contain at least one vowel sound.","example":"Cat (1), Rab-bit (2), Com-pu-ter (3), El-e-phant (3), Com-pu-ta-tion (4)","strategyClue":"Clap your hands or tap your chin for every vowel sound you hear as you say the word slowly. The number of taps equals the number of syllables.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: three. The word 'computer' is divided into three distinct syllables: com-pu-ter. Each syllable contains one vowel sound.","incorrect":[{"choice":"two","category":"syllable count error","reason":"Saying 'com-puter' only counts two beats. Remember that the 'pu' sound is a separate syllable from the 'ter' sound."},{"choice":"one","category":"syllable count error","reason":"A word with only one syllable is a monosyllabic word. 'Computer' is much longer and has three distinct parts when spoken aloud."},"",{"choice":"four","category":"syllable count error","reason":"Counting four syllables creates extra sounds that aren't there. If you say 'com-pu-t-er', you are accidentally adding a sound that doesn't exist in the word."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":101,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0102","version":3,"contentHash":"sha256:d81c4794eb429bbbceaff8487891e9ba17553b8bf36c804627d1c647114714bb","question":"Grade 4 Easy: Choose the best answer. Which word has a closed first syllable?","choices":["music","paper","tiger","rabbit"],"correct":3,"studyAid":{"definition":"A closed syllable ends in a consonant and usually has a short vowel sound. An open syllable ends in a vowel and usually has a long vowel sound.","example":"Closed: cat (ends in t), basket (bas-ket); Open: go, me, baby (ba-by).","strategyClue":"Divide the word into two parts. Look at the very first part: if it ends in a consonant and the vowel sounds short, it is a closed syllable.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: rabbit. A closed syllable ends in at least one consonant, which makes the vowel sound short. In 'rab-bit', the first syllable 'rab' ends in the consonant 'b', making the 'a' sound short.","incorrect":[{"choice":"music","category":"open syllable error","reason":"The first syllable 'mu' ends in a vowel, making it an open syllable with a long vowel sound. Closed syllables must end in a consonant."},{"choice":"paper","category":"open syllable error","reason":"The first syllable 'pa' ends with a long vowel sound and no following consonant, which makes it an open syllable, not a closed one."},{"choice":"tiger","category":"open syllable error","reason":"The first syllable 'ti' ends in a vowel and has a long vowel sound, meaning it is an open syllable rather than a closed one."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":102,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0103","version":3,"contentHash":"sha256:a9654416c5f90408bfcff62ece313b7442babe9fbd26f31a2b2cdb3b04edf741","question":"Grade 4 Easy: Choose the best answer. Which word uses ai to spell the long a sound?","choices":["rain","said","plaid","captain"],"correct":0,"studyAid":{"definition":"A vowel team is two vowels placed together that work as a team to represent a single sound, such as the long 'a' sound in 'ai'.","example":"rain (long a), wait (long a), fail (long a)","strategyClue":"Say each word out loud slowly and listen for the specific long 'a' sound. If you hear the name of the letter 'A', that word is a match.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: rain. In the word 'rain', the 'ai' vowel team works together to create the long 'a' sound (the /eɪ/ phoneme).","incorrect":["",{"choice":"said","category":"irregular vowel sound","reason":"Although 'said' contains the letters 'ai', they do not make the long 'a' sound; instead, they make a short 'e' sound."},{"choice":"plaid","category":"irregular vowel sound","reason":"In 'plaid', the 'ai' combination creates a short 'a' sound (like in 'cat'), not the long 'a' sound."},{"choice":"captain","category":"short vowel sound","reason":"The 'ai' in 'captain' is part of an unstressed syllable and produces a quick, short sound rather than the distinct long 'a' sound."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":103,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0104","version":3,"contentHash":"sha256:934d4ecf3b00a852d86b848e4b767cf4b7d9b26efef8ea622771d3a61137ee76","question":"Grade 4 Easy: Choose the best answer. Which word has an r-controlled vowel?","choices":["bride","bird","bread","brush"],"correct":1,"studyAid":{"definition":"An r-controlled vowel is a syllable where the vowel is followed by an 'r', which changes the vowel's sound to something like 'ar', 'er', 'ir', 'or', or 'ur'.","example":"car (ar), fern (er), bird (ir), corn (or), surf (ur)","strategyClue":"Say each word aloud slowly and listen for the sound change. Look for words where the vowel and the 'r' combine to create a single, unique 'r-flavored' sound.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: bird. An r-controlled vowel occurs when the letter 'r' changes the sound of the vowel before it. In 'bird', the 'i' is controlled by the 'r' to make the 'er' sound.","incorrect":[{"choice":"bride","category":"long vowel pattern","reason":"In 'bride', the 'i' has a long sound (i) because of the silent 'e' at the end. The 'r' is part of a consonant blend, not a vowel controller."},"",{"choice":"bread","category":"vowel team pattern","reason":"In 'bread', the letters 'e' and 'a' work together as a team to make a short vowel sound. The 'r' is just a consonant following the vowel team."},{"choice":"brush","category":"consonant blend","reason":"In 'brush', the 'u' makes a short sound. The 'r' here is part of the 'br' consonant blend at the beginning of the word, not controlling the 'u'."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":104,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0105","version":3,"contentHash":"sha256:1ca85f0871c6593a8ef64710df8e2e59e6ad2fb3c5d12b9cbb030aaf72128939","question":"Grade 4 Easy: Choose the best answer. Which word contains a silent letter?","choices":["sock","rock","knock","lock"],"correct":2,"studyAid":{"definition":"A silent letter is a letter that appears in a word's spelling but does not make a sound when you speak the word.","example":"wrong (the 'w' is silent), gnome (the 'g' is silent), climb (the 'b' is silent)","strategyClue":"Say each word out loud very slowly and carefully. Listen for which word has a letter at the beginning that you cannot hear in the sound.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: knock. The letter 'k' at the beginning of 'knock' is silent because it is not pronounced when you say the word aloud.","incorrect":[{"choice":"sock","category":"pronounced consonants","reason":"Every letter in 'sock' is pronounced. The 's', 'o', 'c', and 'k' all contribute to the sound of the word."},{"choice":"rock","category":"pronounced consonants","reason":"All the letters in 'rock' are voiced. You can clearly hear the 'r', the 'o', the 'c', and the 'k' sounds."},"",{"choice":"lock","category":"pronounced consonants","reason":"The word 'lock' does not have a silent letter. You hear the sounds for every letter present in the word."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":105,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0106","version":3,"contentHash":"sha256:6dc7436a547f41748742ae4182fa5158dbad783b68c5e536215afdcb8f629edc","question":"Grade 4 Medium: Use the context to choose the best answer. Which word uses ai to spell the long a sound?","choices":["said","plaid","captain","rain"],"correct":3,"studyAid":{"definition":"The 'ai' vowel team is one way to spell the long 'a' sound, which is most often found in the middle of a syllable.","example":"rain (long a), mail (long a), wait (long a)","strategyClue":"Say each word out loud slowly. Listen for the sound of the letter 'A' saying its own name ('ay') and identify which word features that sound clearly.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: rain. In the word 'rain', the 'ai' spelling creates a clear long 'a' sound. This is a common vowel team pattern where two vowels go walking together and the first one does the talking by saying its long name.","incorrect":[{"choice":"said","category":"irregular spelling","reason":"Although 'said' contains the letters 'ai', it is an irregular word that sounds like a short 'e'. It does not follow the long 'a' vowel team rule."},{"choice":"plaid","category":"irregular spelling","reason":"In 'plaid', the 'ai' combination makes a short 'a' sound (like in 'cat'). It does not create the long 'a' sound required."},{"choice":"captain","category":"vowel sound variation","reason":"In 'captain', the 'ai' pair is in an unstressed syllable and sounds more like a short 'i' or a schwa sound. It is not pronounced with the long 'a' sound."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":106,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0107","version":3,"contentHash":"sha256:001d7086b32a0bca20ef54029d4cd121d2c02fcab112f52695298fda628a8a3e","question":"Grade 4 Medium: Use the context to choose the best answer. Which word has an r-controlled vowel?","choices":["bird","bride","bread","brush"],"correct":0,"studyAid":{"definition":"An r-controlled vowel occurs when a vowel is followed by the letter 'r', causing the vowel to lose its standard long or short sound and take on a new sound.","example":"bird (ir), car (ar), corn (or), fern (er), fur (ur)","strategyClue":"Say each word aloud slowly and listen for the vowel. Look for words where the 'r' pulls the vowel's sound into a growling 'er' tone.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: bird. In this word, the vowel 'i' is followed by an 'r', which changes the vowel's sound to create the 'er' sound. This is known as an r-controlled vowel.","incorrect":["",{"choice":"bride","category":"long vowel sound","reason":"The 'i' in 'bride' makes a long vowel sound because of the silent 'e' at the end. It is not controlled by the 'r'."},{"choice":"bread","category":"vowel team","reason":"The 'ea' in 'bread' is a vowel team where two vowels work together to make a short 'e' sound. The 'r' does not change the vowel sound here."},{"choice":"brush","category":"short vowel sound","reason":"The 'u' in 'brush' makes a short vowel sound. The 'r' is part of a consonant blend at the beginning, but it does not control the vowel sound."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":107,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0108","version":3,"contentHash":"sha256:6ce6404a28d6778b020c6c9158db9a97ea2c94b9f6df11ad7d6e285c25ec492b","question":"Grade 4 Medium: Use the context to choose the best answer. Which word contains a silent letter?","choices":["rock","knock","sock","lock"],"correct":1,"studyAid":{"definition":"A silent letter is a letter that is part of a word's spelling but is not heard when the word is spoken.","example":"wrote (the 'w' is silent), thumb (the 'b' is silent), sign (the 'g' is silent)","strategyClue":"Say each word out loud slowly and check if every letter has a matching sound. If you find a letter that seems to disappear when you speak, that is your silent letter.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: knock. The letter 'k' at the beginning of 'knock' is silent. It is not heard when you pronounce the word, unlike the clear sounds in the other options.","incorrect":[{"choice":"rock","category":"pronounced consonants","reason":"In the word 'rock', the letter 'r' is clearly heard. There are no silent letters in this word."},"",{"choice":"sock","category":"pronounced consonants","reason":"The 's' at the start of 'sock' is fully pronounced. This word does not contain any silent letters."},{"choice":"lock","category":"pronounced consonants","reason":"In 'lock', the 'l' sound is clearly audible at the start. Every letter in this word contributes to its sound."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":108,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0109","version":3,"contentHash":"sha256:7b7bcfaad8accee0451b772c2b8ffff60a3f65bdaedb93c9a6ad6648b1f2a4c8","question":"Grade 4 Medium: Use the context to choose the best answer. Which spelling is correct?","choices":["becaus","becuase","because","beacuse"],"correct":2,"studyAid":{"definition":"The word 'because' is a subordinating conjunction used to show a cause or reason. It is spelled with the letters b-e-c-a-u-s-e.","example":"I wore a coat because it was cold. We left because the show was over.","strategyClue":"Try to visualize the word by breaking it into syllables: 'be-cause'. Focus on the middle part where 'a' comes before 'u'.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: because. The correct spelling is 'because', which follows the standard English pattern for this conjunction.","incorrect":[{"choice":"becaus","category":"missing terminal letter","reason":"This spelling is missing the final 'e' that is necessary to complete the word correctly."},{"choice":"becuase","category":"vowel transposition error","reason":"You have swapped the order of the 'u' and the 'a'. Ensure the 'a' comes before the 'u' when spelling this word."},"",{"choice":"beacuse","category":"vowel transposition error","reason":"The 'a' and the 'u' are in the wrong positions here; the correct sequence is 'a' followed by 'u' before the 's'."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":109,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0110","version":3,"contentHash":"sha256:e1a9ea17ac4817c683e7eadd8a181ffb01eb5fb6f9a5a50db6d08daf16b0dd2f","question":"Grade 4 Medium: Use the context to choose the best answer. The root photo means light. What does photograph most nearly mean?","choices":["a kind of water","a sound made underground","a person who writes","a picture made with light"],"correct":3,"studyAid":{"definition":"A root word is the base part of a word that carries its main meaning. Knowing the root 'photo' helps you understand words related to light.","example":"photosynthesis (using light to make food), photocopy (making a copy with light), photographer (a person who uses light to take pictures)","strategyClue":"Break the word into parts and apply the definition of the root. Ask yourself which option connects the definition of 'photo' to the meaning of the whole word.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: a picture made with light. Since the root 'photo' means light and 'graph' relates to drawing or writing, a photograph is a way to 'write' or capture an image using light.","incorrect":[{"choice":"a kind of water","category":"incorrect root definition","reason":"Water is not related to the root 'photo'. If you see 'photo', look for meanings involving light or brightness."},{"choice":"a sound made underground","category":"incorrect root definition","reason":"The root 'photo' refers to light, not sound. Sound-related words often use roots like 'phon', but this choice does not describe light at all."},{"choice":"a person who writes","category":"incorrect part of speech","reason":"While a photograph involves a kind of 'writing' with light, the word 'photograph' refers to the picture itself, not the person who creates it."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":110,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0111","version":3,"contentHash":"sha256:39d1784f356c063ecf25cac29210f1d988be62824287479f91e8be16c4e3e1d6","question":"Grade 4 Medium: Use the context to choose the best answer. The root port means carry. What does portable mean?","choices":["able to be carried","full of light","against water","not visible"],"correct":0,"studyAid":{"definition":"A root word is the base part of a word that carries its main meaning, and a suffix is added to the end to change or clarify that meaning.","example":"Portable (able to be carried), Washable (able to be washed), Breakable (able to be broken)","strategyClue":"Split the word into two parts: the base and the ending. Define the root 'port' as carrying and the suffix '-able' as 'can be done' to see which definition matches.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: able to be carried. The suffix '-able' means 'able to be' and the root 'port' means 'carry', so portable means something that is easy to move or carry.","incorrect":["",{"choice":"full of light","category":"incorrect suffix meaning","reason":"The suffix '-able' does not relate to light. '-able' means capable of being done or having a specific quality, not being full of light."},{"choice":"against water","category":"incorrect root meaning","reason":"The root 'port' relates to carrying, like in 'transport' or 'export', not to water. Words relating to 'against' or 'water' would use different prefixes and roots."},{"choice":"not visible","category":"incorrect prefix usage","reason":"This definition describes something like 'invisible'. It does not contain the meaning of the root 'port', which focuses on movement, not sight."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":111,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0112","version":3,"contentHash":"sha256:fb6a2df4283110adb87d5cb0da5e677797ea4edfe085a8807c25b70da5e7e5ae","question":"Grade 4 Medium: Use the context to choose the best answer. In \"The bat flew at dusk,\" what does bat mean?","choices":["a stick used in baseball","a flying mammal","to hit something","a folded paper"],"correct":1,"studyAid":{"definition":"Words that are spelled the same but have different meanings are called homonyms. You must use the surrounding words in a sentence to figure out which meaning is intended.","example":"He hit the ball with his bat (sports equipment). The bat flew through the dark cave (animal).","strategyClue":"Look at the action described in the sentence, such as 'flew,' and ask yourself which of the choices is capable of doing that specific action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: a flying mammal. The context clue 'flew at dusk' tells us the word refers to a creature that is active at night, which describes the nocturnal animal known as a bat.","incorrect":[{"choice":"a stick used in baseball","category":"homonym confusion","reason":"While a baseball bat is a common meaning of the word, it does not fit the context here because a wooden stick cannot fly."},"",{"choice":"to hit something","category":"verb vs noun confusion","reason":"This definition describes the verb 'to bat,' but the sentence uses 'bat' as a noun that performs the action of flying."},{"choice":"a folded paper","category":"incorrect word definition","reason":"This does not match the meaning of the word 'bat.' Always check if the definition provided makes logical sense when placed back into the sentence."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":112,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0113","version":3,"contentHash":"sha256:f4afd83b4b286c9caac34e6569913419ad1822c40af5d523a35730c2f67b92d1","question":"Grade 4 Medium: Use the context to choose the best answer. In \"Please park the car near the park,\" which word has two meanings?","choices":["near","please","park","car"],"correct":2,"studyAid":{"definition":"Homonyms are words that are spelled and pronounced the same way but have completely different meanings.","example":"Bat (a flying animal) vs. Bat (a wooden club for sports); Well (healthy) vs. Well (a hole in the ground for water).","strategyClue":"Test each word by trying to define it in two different ways. Ask yourself: 'Could this word represent an object, a place, or an action?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: park. In this sentence, 'park' is a homonym. It acts as a verb meaning to leave a vehicle in a specific place, and also as a noun meaning a public area of land with trees and grass.","incorrect":[{"choice":"near","category":"prepositional usage","reason":"The word 'near' functions as a preposition indicating location or proximity; it does not have an alternate meaning as a noun or verb in this context."},{"choice":"please","category":"polite adverb","reason":"The word 'please' is used here to make a polite request. While it can be a verb meaning to satisfy someone, it does not fit the dual noun/verb context within this specific sentence."},"",{"choice":"car","category":"singular concrete noun","reason":"The word 'car' is a noun referring to a motor vehicle. It does not have multiple common meanings that function in this sentence structure."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":113,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0114","version":3,"contentHash":"sha256:28dc7829e979570e05c4bc4902d0a466528ce702a7e5e81d54285dadceb8ccfc","question":"Grade 4 Medium: Use the context to choose the best answer. Which word has the strongest meaning?","choices":["went","walked","moved","sprinted"],"correct":3,"studyAid":{"definition":"Stronger verbs give the reader a clearer, more exciting picture of an action by being more specific than basic movement words.","example":"Instead of 'walked,' use 'trudged' or 'strutted.' Instead of 'said,' use 'shouted' or 'whispered.'","strategyClue":"Imagine the action in your mind. If you can replace a word with a more descriptive one that tells you exactly HOW the action happened, that word is stronger.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: sprinted. This word has the strongest meaning because it specifically describes running very quickly, whereas the other options are general or imply a slower pace.","incorrect":[{"choice":"went","category":"general verb choice","reason":"The word 'went' is very broad and does not tell us anything about how fast or in what manner the person traveled."},{"choice":"walked","category":"slower action verb","reason":"'Walked' describes a steady, casual pace, which is the opposite of a fast or intense action."},{"choice":"moved","category":"vague action verb","reason":"'Moved' is a generic term that describes a change in position but fails to convey the intensity or high speed of 'sprinted'."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":114,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0115","version":3,"contentHash":"sha256:872714b8e6aeb33b4cdf6b2b6066b73b5f749c94953947f7637b87c2730f0fbd","question":"Grade 4 Medium: Use the context to choose the best answer. Which word is gentler than furious?","choices":["upset","enraged","livid","explosive"],"correct":0,"studyAid":{"definition":"Synonyms are words that have similar meanings, but they can vary in their 'degree of intensity' or how strong the feeling is.","example":"Annoyed (mild) < Angry (medium) < Furious (strong).","strategyClue":"Think of an 'anger thermometer' in your head. Imagine the word 'furious' at the top of the scale, then look for the option that represents a lower, less extreme temperature on that scale.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: upset. The word 'furious' describes an extreme state of anger. 'Upset' describes a milder or less intense feeling, making it the gentler option among the choices.","incorrect":["",{"choice":"enraged","category":"synonym intensity","reason":"To be 'enraged' means to be extremely angry. This is similar in intensity to 'furious' and is not a gentler way to describe someone's feelings."},{"choice":"livid","category":"synonym intensity","reason":"'Livid' is a strong word used to describe someone who is furiously angry. Because it is just as intense as 'furious', it is not the gentler option."},{"choice":"explosive","category":"synonym intensity","reason":"'Explosive' describes an anger that is violent or sudden. This is much stronger than 'furious', so it does not fit the requirement for a gentler word."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":115,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0116","version":3,"contentHash":"sha256:acfa5df6e64b3a753260f6101b1c84a2a9ffa5d20e6080724114c47f69eda995","question":"Grade 4 Medium: Use the context to choose the best answer. How many syllables are in computer?","choices":["one","three","two","four"],"correct":1,"studyAid":{"definition":"A syllable is a single, unbroken sound of a spoken word. Every syllable contains at least one vowel sound.","example":"cat (1 syllable), rab-bit (2 syllables), com-pu-ter (3 syllables)","strategyClue":"Place your hand under your chin and say the word slowly. Count how many times your chin drops to meet your hand; each drop is one syllable.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: three. To find the number of syllables, break the word into parts based on vowel sounds: com-pu-ter. Since there are three distinct sounds, the word has three syllables.","incorrect":[{"choice":"one","category":"syllable count error","reason":"The word 'computer' has more than one beat or part. Saying it as one sound ignores the natural breaks between syllables."},"",{"choice":"two","category":"syllable count error","reason":"You have identified two parts, but 'computer' has three distinct vowel sounds. Try clapping out the beats: com (1) - pu (2) - ter (3)."},{"choice":"four","category":"syllable count error","reason":"The word 'computer' only has three main parts. Adding a fourth sound makes the word longer than it actually is."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":116,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0117","version":3,"contentHash":"sha256:9eded6afc61edf20efece216840b66ad8cee4e367c7fc900e68bdeda60d9fdb4","question":"Grade 4 Medium: Use the context to choose the best answer. Which word has a closed first syllable?","choices":["tiger","paper","rabbit","music"],"correct":2,"studyAid":{"definition":"A closed syllable ends in at least one consonant and usually contains a short vowel sound.","example":"Closed: cat, pen, rab-bit. Open: go, me, ti-ger.","strategyClue":"Divide the word into two syllables. Look at the first syllable and see if it ends with a consonant or a vowel; if it ends in a consonant, check if the vowel sound is short.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: rabbit. A closed syllable ends in a consonant and has a short vowel sound. In 'rab-bit', the first syllable 'rab' ends in the consonant 'b', making it a closed syllable.","incorrect":[{"choice":"tiger","category":"open syllable error","reason":"The first syllable 'ti' ends in a vowel and has a long vowel sound. This makes it an open syllable, not a closed one."},{"choice":"paper","category":"open syllable error","reason":"The first syllable 'pa' ends in the letter 'a' and has a long vowel sound, which is the definition of an open syllable."},"",{"choice":"music","category":"open syllable error","reason":"The first syllable 'mu' ends with the vowel 'u' and sounds like 'mew', which is an open syllable."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":117,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0118","version":3,"contentHash":"sha256:57fde984c4c5de6b3a1fb3fe55997022d2b7af0efe67de502a8b498a749d886b","question":"Grade 4 Medium: Use the context to choose the best answer. Which word uses ai to spell the long a sound?","choices":["said","plaid","captain","rain"],"correct":3,"studyAid":{"definition":"The 'ai' letter team often makes a long 'a' sound in the middle of a word. However, some words are 'rule-breakers' and use these letters to make different sounds.","example":"Long A: rain, mail, paint. Rule-breakers: said (short e), plaid (short a).","strategyClue":"Say each word out loud slowly. Listen for the sound that matches the name of the letter 'A'. Choose the word where 'ai' creates that specific sound.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: rain. In the word 'rain', the 'a' and 'i' work together to make a clear, long 'a' sound like in the word 'play'.","incorrect":[{"choice":"said","category":"short e sound","reason":"Although 'said' is spelled with 'ai', it makes a short 'e' sound, not the long 'a' sound we are looking for."},{"choice":"plaid","category":"short a sound","reason":"In the word 'plaid', the 'ai' combination creates a short 'a' sound, which is different from the long 'a' sound in 'rain'."},{"choice":"captain","category":"short i sound","reason":"In the word 'captain', the 'ai' team makes a very short, quick sound instead of the long 'a' sound heard in words like 'train' or 'rain'."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":118,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0119","version":3,"contentHash":"sha256:aa11348fa9199e00fcf7da79fef8628c63edd276d048a6290d066eff373a3c1a","question":"Grade 4 Medium: Use the context to choose the best answer. Which word has an r-controlled vowel?","choices":["bird","bride","bread","brush"],"correct":0,"studyAid":{"definition":"An r-controlled vowel occurs when the letter 'r' follows a vowel and changes the way that vowel sounds. Common patterns include 'ar', 'er', 'ir', 'or', and 'ur'.","example":"car (ar), fern (er), bird (ir), horn (or), turn (ur)","strategyClue":"Say each word out loud slowly and listen for the sound change. If the 'r' makes the vowel sound like a smooth, deep, or 'growling' sound rather than its usual short or long sound, you have found an r-controlled vowel.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: bird. In this word, the 'ir' combination forms an r-controlled vowel. The letter 'r' changes the 'i' so it makes a unique sound rather than a short or long vowel sound.","incorrect":["",{"choice":"bride","category":"long vowel sound","reason":"The 'i' in 'bride' makes a long vowel sound because of the silent 'e' at the end, not an r-controlled sound."},{"choice":"bread","category":"vowel team","reason":"The 'ea' in 'bread' is a vowel team working together to make a short 'e' sound. It is not influenced by an 'r'."},{"choice":"brush","category":"short vowel sound","reason":"The 'u' in 'brush' makes a short vowel sound. The 'r' here is part of a consonant blend ('br'), not an r-controlled vowel."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":119,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0120","version":3,"contentHash":"sha256:86cb364297bb041daa4f3113852c8def9d9e68929c55dc86bb5f871e695eba83","question":"Grade 4 Medium: Use the context to choose the best answer. Which word contains a silent letter?","choices":["rock","knock","sock","lock"],"correct":1,"studyAid":{"definition":"A silent letter is a letter that appears in the written spelling of a word but is not pronounced when the word is spoken aloud.","example":"wrote (silent w), thumb (silent b), knife (silent k)","strategyClue":"Say each word aloud slowly and carefully. Identify every sound you hear, then compare those sounds to the letters written in the word to see if any are skipped.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: knock. The 'k' at the beginning of 'knock' is silent because it is not pronounced. You only hear the 'n', 'o', 'c', and 'k' sounds.","incorrect":[{"choice":"rock","category":"pronounced consonants","reason":"Every letter in 'rock' is pronounced. You can clearly hear the 'r' sound at the beginning of the word."},"",{"choice":"sock","category":"pronounced consonants","reason":"The 's' in 'sock' is a voiced consonant sound. Since you can hear it, it is not a silent letter."},{"choice":"lock","category":"pronounced consonants","reason":"The 'l' in 'lock' is pronounced at the start of the word, so it does not count as a silent letter."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":120,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0121","version":3,"contentHash":"sha256:2c1c3ffffa7d3b63844a8533934cef28934f28972d8b9b8c8c729767242d15ba","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. Which word uses ai to spell the long a sound?","choices":["said","plaid","rain","captain"],"correct":2,"studyAid":{"definition":"A vowel team is two vowels next to each other that work together to make one long vowel sound, such as 'ai' creating the long 'a'.","example":"rain (long a), wait (long a), mail (long a)","strategyClue":"Say each word out loud slowly and listen for the /eɪ/ sound of the letter 'a' naming itself. Select the word where you hear the 'a' sound clearly.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: rain. In the word 'rain', the letters 'ai' work together to create the long 'a' sound (/eɪ/).","incorrect":[{"choice":"said","category":"irregular vowel sound","reason":"Although 'said' is spelled with 'ai', it makes a short 'e' sound, not the long 'a' sound."},{"choice":"plaid","category":"irregular spelling rule","reason":"The word 'plaid' is spelled with 'ai', but it makes a short 'a' sound, like in the word 'cat'."},"",{"choice":"captain","category":"vowel team reduction","reason":"In 'captain', the 'ai' spelling appears, but it is part of an unstressed syllable and makes a short 'i' or 'schwa' sound rather than a clear long 'a'."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":121,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0122","version":3,"contentHash":"sha256:c5e91ab9203136256af4d6e8017c6a790d769b1c6fb7136986ef657e354dbbe4","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. Which word has an r-controlled vowel?","choices":["bride","bread","brush","bird"],"correct":3,"studyAid":{"definition":"An r-controlled vowel occurs when a vowel is followed immediately by the letter 'r', causing the vowel to lose its normal short or long sound.","example":"bird (ir), star (ar), fern (er), corn (or), burn (ur)","strategyClue":"Look for a word where the 'r' comes directly after the vowel. Say each word out loud and listen for the 'er', 'ar', or 'or' sound produced by the vowel-r combination.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: bird. In this word, the vowel 'i' is followed by an 'r', which changes the vowel's sound to the 'er' sound. This is known as an r-controlled vowel.","incorrect":[{"choice":"bride","category":"long vowel sound","reason":"In 'bride', the 'i' has a long sound because of the silent 'e' at the end. It is not being controlled by the 'r'."},{"choice":"bread","category":"vowel team","reason":"In 'bread', the letters 'ea' work together as a vowel team to make a short 'e' sound. The 'r' is not controlling the vowel sound here."},{"choice":"brush","category":"short vowel sound","reason":"In 'brush', the 'u' makes a short sound. While the word has an 'r', the 'r' comes before the vowel, so it does not control the vowel's sound."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":122,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0123","version":3,"contentHash":"sha256:a26e504535b9ba386b0c54a63bd1ba69ad9eeebd1b679a3d5357e8996d4e40a7","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. Which word contains a silent letter?","choices":["knock","rock","sock","lock"],"correct":0,"studyAid":{"definition":"A silent letter is a letter that appears in a written word but is not heard when the word is spoken.","example":"knock (silent k), thumb (silent b), write (silent w)","strategyClue":"Say each word out loud very slowly and track which letters produce a sound. If you find a letter that has no corresponding sound, you have found the silent letter.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: knock. The letter 'k' at the beginning of 'knock' is silent because it is not pronounced when speaking the word; we only hear the 'n' sound.","incorrect":["",{"choice":"rock","category":"pronounced consonant sound","reason":"The 'r' at the start of 'rock' is clearly pronounced. Every letter in this word contributes to its sound."},{"choice":"sock","category":"pronounced consonant sound","reason":"In 'sock', the 's' is fully pronounced. There are no hidden or silent letters in this word."},{"choice":"lock","category":"pronounced consonant sound","reason":"The 'l' in 'lock' is heard clearly when you say the word aloud. It does not contain a silent letter."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":123,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0124","version":3,"contentHash":"sha256:4e3f4af9d2f5c1cbf17d0649057676d62b45493d98ff7c6e246fec0bcbd4d6a1","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. Which spelling is correct?","choices":["becuase","because","becaus","beacuse"],"correct":1,"studyAid":{"definition":"The word 'because' is a subordinating conjunction used to show a cause or reason. It is often misspelled, so it is helpful to remember it is composed of 'be' + 'cause'.","example":"I stayed inside because it was raining. She was happy because she won the game.","strategyClue":"Try breaking the word into two parts in your mind: 'be' and 'cause'. Check if the second part matches the spelling of the word for a legal reason.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: because. The correct spelling of this conjunction requires an 'a' after the 'c' and ends with an 'e'.","incorrect":[{"choice":"becuase","category":"vowel sequence error","reason":"This spelling puts the 'u' before the 'a', which does not match the standard spelling of this word."},"",{"choice":"becaus","category":"missing final vowel","reason":"This spelling leaves off the silent 'e' at the end, which is a required part of the complete word."},{"choice":"beacuse","category":"letter transposition","reason":"This spelling swaps the order of the 'u' and the 's', making the middle of the word incorrect."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":124,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0125","version":3,"contentHash":"sha256:028e6b4570d2affa994d994620d7d354f786184f99df751824300c6735e61f0b","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. The root photo means light. What does photograph most nearly mean?","choices":["a person who writes","a sound made underground","a picture made with light","a kind of water"],"correct":2,"studyAid":{"definition":"A word root is a basic part of a word that carries its main meaning. Knowing common Greek and Latin roots helps you figure out the meaning of unfamiliar words.","example":"photo (light) + graph (write/draw) = photograph; tele (distant) + phone (sound) = telephone","strategyClue":"Split the word into two parts: the beginning root and the ending. Recall or search for the definition of the root provided in the prompt to eliminate options that do not relate to that specific meaning.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: a picture made with light. The Greek root 'photo-' means 'light' and the suffix '-graph' relates to writing or drawing. Therefore, a photograph is literally a way of 'drawing with light.'","incorrect":[{"choice":"a person who writes","category":"incorrect suffix meaning","reason":"This definition relates more to the root 'graph' (writing), but it ignores the 'photo' part of the word, which specifically relates to light, not people."},{"choice":"a sound made underground","category":"unrelated definition","reason":"This choice does not match the roots of the word. 'Photo' refers to light, so a definition involving sound is incorrect."},"",{"choice":"a kind of water","category":"incorrect root meaning","reason":"The root 'photo-' relates to light. Water is often associated with the root 'hydro-', which is not present in this word."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":125,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0126","version":3,"contentHash":"sha256:5863761e018a7ce652a4fdd2844b7d2728edcbbff8927d2d293ab92a04a903f9","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. The root port means carry. What does portable mean?","choices":["not visible","full of light","against water","able to be carried"],"correct":3,"studyAid":{"definition":"A root word is the base part of a word that carries its main meaning, and suffixes are added to the end to change that meaning.","example":"Portable (able to be carried), Transport (carry across), Report (carry back information).","strategyClue":"Split the word into its parts: the root 'port' and the suffix '-able.' Think of what it means to carry something, then add the meaning of the ending suffix to build the definition.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: able to be carried. The suffix '-able' means 'able to be,' and when combined with the root 'port' (carry), it creates the meaning 'able to be carried.'","incorrect":[{"choice":"not visible","category":"incorrect prefix meaning","reason":"This choice incorrectly associates the root with sight. 'Port' relates to movement or carrying, not seeing or being visible."},{"choice":"full of light","category":"incorrect suffix meaning","reason":"The suffix '-able' means 'able to be,' not 'full of.' Other suffixes like '-ful' would indicate being 'full of' something."},{"choice":"against water","category":"incorrect root interpretation","reason":"This choice describes the prefix 'anti-' (against), not the root 'port.' Always look for the 'carry' definition when you see 'port' in a word."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":126,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0127","version":3,"contentHash":"sha256:98a08218356ad0238919c478d8861329e20c77e52be8c122241d926924ee361f","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. In \"The bat flew at dusk,\" what does bat mean?","choices":["a flying mammal","a stick used in baseball","to hit something","a folded paper"],"correct":0,"studyAid":{"definition":"Words that are spelled the same but have different meanings are called homonyms. Context clues in the sentence help you determine which definition is correct.","example":"He swung the bat (sports equipment). The bat slept in the cave (animal).","strategyClue":"Identify the verb in the sentence and ask yourself what kind of object would reasonably perform that action. If an object is flying, it is likely an animal rather than a tool.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: a flying mammal. In the context of 'flew at dusk,' the word 'bat' refers to the nocturnal creature capable of flight, not a piece of sports equipment or an action.","incorrect":["",{"choice":"a stick used in baseball","category":"confusing homonyms","reason":"While this is a common definition for 'bat,' a baseball bat cannot fly. Look for clues about movement or time of day to determine the correct meaning."},{"choice":"to hit something","category":"verb versus noun","reason":"This is a verb form of 'bat,' but the sentence structure uses 'bat' as a noun (the subject performing the action of flying)."},{"choice":"a folded paper","category":"incorrect definition","reason":"This definition does not match the word 'bat' at all. Always look for context clues that relate to animals or nature when you see words with multiple meanings."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":127,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0128","version":3,"contentHash":"sha256:82da9d748ae3e37c1e9e0c045059e04ba4b322e30dd559cf8cc8c12bd8c06eb8","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. In \"Please park the car near the park,\" which word has two meanings?","choices":["please","park","near","car"],"correct":1,"studyAid":{"definition":"Homonyms are words that are spelled and pronounced the same but have different meanings depending on how they are used in a sentence.","example":"Bat (a flying animal vs. sports equipment), Bank (side of a river vs. a place for money), Well (healthy vs. a water hole).","strategyClue":"Try defining each word individually. If you can create two very different images for the same word—like a place for play versus the act of stopping a car—you have found a homonym.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: park. The word 'park' is a homonym: it can be a verb meaning to leave a vehicle in a specific spot, and a noun meaning an area of land used for recreation.","incorrect":[{"choice":"please","category":"single meaning verb","reason":"The word 'please' is used to show politeness or as a verb meaning to make someone happy. It does not change its definition based on the context of this sentence."},"",{"choice":"near","category":"prepositional usage","reason":"The word 'near' acts as a preposition showing location. It does not have a second common definition that would fit into this sentence structure."},{"choice":"car","category":"single meaning noun","reason":"The word 'car' refers specifically to a motorized vehicle. It is a concrete noun and does not have multiple common meanings that function here."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":128,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0129","version":3,"contentHash":"sha256:9e1605316d5cb3c3f230880396b8de950c08973550a8c0e84f87294ab595268c","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. Which word has the strongest meaning?","choices":["moved","walked","sprinted","went"],"correct":2,"studyAid":{"definition":"Stronger verbs give the reader a more vivid picture of an action by being specific rather than general.","example":"Instead of 'said', use 'whispered' or 'shouted'. Instead of 'ate', use 'devoured'.","strategyClue":"Visualize each verb in your mind and rank them by the level of energy or speed they suggest. Choose the one that paints the most intense or specific picture.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: sprinted. The word 'sprinted' is the strongest choice because it specifically describes running at full speed, whereas the others describe general movement.","incorrect":[{"choice":"moved","category":"vague verb choice","reason":"The word 'moved' is very general and does not provide a clear picture of how quickly someone is traveling."},{"choice":"walked","category":"low intensity verb","reason":"Walking is a slow or moderate action, which lacks the speed and power conveyed by more descriptive verbs."},"",{"choice":"went","category":"imprecise verb choice","reason":"The word 'went' is a basic verb that does not tell the reader anything about the speed or energy used in the movement."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":129,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0130","version":3,"contentHash":"sha256:8eb6c2261680865744b1b1b24b821a103ce3c023635e266310f4be5c540e0505","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. Which word is gentler than furious?","choices":["explosive","enraged","livid","upset"],"correct":3,"studyAid":{"definition":"Synonyms are words with similar meanings, but they often have different levels of intensity. Some words describe mild feelings, while others describe extreme ones.","example":"Gentle: happy, Strong: ecstatic; Gentle: sad, Strong: miserable; Gentle: hungry, Strong: starving.","strategyClue":"Imagine a scale of intensity from 1 to 10. Think about how much energy or power each word expresses and pick the one that falls lower on that scale.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: upset. The word 'upset' describes a mild to moderate level of emotional disturbance, whereas 'furious' implies a very intense state of extreme anger.","incorrect":[{"choice":"explosive","category":"intensifying adjective","reason":"The word 'explosive' suggests a sudden and violent display of anger, making it just as strong or even more intense than 'furious'."},{"choice":"enraged","category":"synonym for furious","reason":"'Enraged' means to be filled with great anger. This word is a synonym for 'furious' and is just as strong, not gentler."},{"choice":"livid","category":"synonym for furious","reason":"'Livid' is an intense adjective used to describe someone who is extremely angry. It carries the same weight as 'furious', not a lighter meaning."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":130,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0131","version":3,"contentHash":"sha256:35eeaaa1c5a5e4a662d07ff4d1eb16998041011a596575dbd12c7d0af233ad9d","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. How many syllables are in computer?","choices":["three","one","two","four"],"correct":0,"studyAid":{"definition":"A syllable is a single unit of sound that contains a vowel sound, acting as a 'beat' in a word.","example":"cat (1), hap-py (2), com-pu-ter (3), e-lec-tri-cal (4)","strategyClue":"Clap your hands or tap your chin for every vowel sound you hear as you say the word slowly. Count the number of claps to find the total syllables.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: three. The word 'computer' is divided into three distinct beats or vowel sounds: com-pu-ter.","incorrect":["",{"choice":"one","category":"syllable count error","reason":"This is too few syllables. Saying the word slowly shows that 'computer' has more than one beat."},{"choice":"two","category":"syllable count error","reason":"This is incorrect because 'computer' has three parts. Only counting two leaves out the final '-ter' sound."},{"choice":"four","category":"syllable count error","reason":"This is too many syllables. 'Computer' does not have four distinct vowel beats when spoken naturally."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":131,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0132","version":3,"contentHash":"sha256:462f084bb8bf624964a8168d27d096e18edf3b849a5b3eb8de7f39621572dc68","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. Which word has a closed first syllable?","choices":["paper","rabbit","tiger","music"],"correct":1,"studyAid":{"definition":"A closed syllable ends in a consonant and has a short vowel sound. An open syllable ends in a vowel and has a long vowel sound.","example":"Closed: cat, pen, sit. Open: go, me, hi.","strategyClue":"Say the first syllable out loud and listen to the vowel. If it sounds short (like in 'at' or 'in'), check if the syllable ends with a consonant letter to lock the vowel in.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: rabbit. A closed syllable ends in at least one consonant after a short vowel sound, which 'rab-' shows as the short 'a' followed by the consonant 'b'.","incorrect":[{"choice":"paper","category":"open syllable error","reason":"The first syllable 'pa-' ends in a long vowel sound 'a', making it an open syllable, not a closed one."},"",{"choice":"tiger","category":"open syllable error","reason":"The first syllable 'ti-' ends in a long vowel sound 'i', which classifies it as an open syllable."},{"choice":"music","category":"open syllable error","reason":"The first syllable 'mu-' ends in a long vowel sound 'u', so it does not fit the definition of a closed syllable."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":132,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0133","version":3,"contentHash":"sha256:c296446b255fa4cdb97f0df9a0803e45b5a50f4f73689e602237da46ccdac798","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. Which word uses ai to spell the long a sound?","choices":["said","plaid","rain","captain"],"correct":2,"studyAid":{"definition":"The vowel team 'ai' commonly represents the long 'a' sound, especially when it appears in the middle of a single-syllable word.","example":"rain, wait, snail (correct); said (irregular)","strategyClue":"Say each word aloud slowly and identify where the vowel sound is placed; look for the word where the two vowels produce the sound of the letter name 'A'.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: rain. In this word, the letters 'ai' work together to create the long 'a' sound (/eɪ/).","incorrect":[{"choice":"said","category":"irregular vowel spelling","reason":"Although this word contains 'ai', it is an irregular sight word where the 'ai' combination creates a short 'e' sound instead of the long 'a' sound."},{"choice":"plaid","category":"irregular vowel spelling","reason":"The 'ai' in this word is pronounced as a short 'a' sound (/æ/), which is different from the long 'a' sound heard in words like 'rain'."},"",{"choice":"captain","category":"vowel team variation","reason":"While this word contains 'ai', the sound is shortened because it is in an unstressed syllable, resulting in a sound similar to a short 'i' or schwa rather than a distinct long 'a'."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":133,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0134","version":3,"contentHash":"sha256:a82c617c73169f32c50a37448b001629292b726513dbff560d86a117ff988b9b","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. Which word has an r-controlled vowel?","choices":["bride","bread","brush","bird"],"correct":3,"studyAid":{"definition":"An r-controlled vowel happens when the letter 'r' follows a vowel, forcing the vowel to lose its normal short or long sound and take on a new, r-influenced sound.","example":"car (ar), her (er), bird (ir), corn (or), fur (ur)","strategyClue":"Say each word aloud slowly. Listen for a vowel sound that blends directly into an 'r' sound, sounding like 'er', 'ar', or 'or', rather than a distinct short or long vowel sound.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: bird. An r-controlled vowel occurs when the letter 'r' follows a vowel and changes the sound that vowel makes. In 'bird', the 'r' controls the 'i' to create the 'er' sound.","incorrect":[{"choice":"bride","category":"long vowel sound","reason":"The word 'bride' features a long 'i' sound followed by a silent 'e'. The 'r' here is part of a consonant blend (br) rather than controlling the vowel sound."},{"choice":"bread","category":"vowel digraph","reason":"The word 'bread' uses a vowel team where 'e' and 'a' work together to make a short 'e' sound. The 'r' is not controlling the vowel here."},{"choice":"brush","category":"short vowel sound","reason":"The word 'brush' has a short 'u' sound. Like 'bride', the 'r' is part of a consonant blend at the beginning of the word and does not affect the vowel sound."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":134,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0135","version":3,"contentHash":"sha256:44369b5b890e773952ae0c7b7ad572809968e224cb526c1dd52c11c33e65ed4d","question":"Grade 4 Hard: Analyze the details and choose the strongest answer. Which word contains a silent letter?","choices":["knock","rock","sock","lock"],"correct":0,"studyAid":{"definition":"A silent letter is a letter that appears in the spelling of a word but is not heard when the word is spoken.","example":"write (silent w), thumb (silent b), knee (silent k)","strategyClue":"Say each word out loud slowly and check if every letter makes a distinct sound. If a letter seems to be skipped over, you have found the silent one.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: knock. The letter 'k' is a silent letter because it is not pronounced when you say the word out loud.","incorrect":["",{"choice":"rock","category":"phonics error","reason":"In the word 'rock', every letter contributes to the sound. The 'r', 'o', 'c', and 'k' are all pronounced."},{"choice":"sock","category":"phonics error","reason":"In the word 'sock', the 's', 'o', 'c', and 'k' all make their own sounds; there are no letters that remain silent."},{"choice":"lock","category":"phonics error","reason":"Every letter in 'lock' is pronounced. The 'l', 'o', 'c', and 'k' all combine to form the sounds in the word."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":135,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0136","version":3,"contentHash":"sha256:9b165bb2c978fba627b5898286ecd15da3493b7127fda028b2f8669a55c6093a","question":"Grade 5 Easy: Choose the best answer. Which word uses ai to spell the long a sound?","choices":["said","plaid","rain","captain"],"correct":2,"studyAid":{"definition":"A vowel team is two vowels side-by-side that work together to create a single long vowel sound.","example":"rain (long a), mail (long a), wait (long a)","strategyClue":"Say each word out loud slowly. Listen for the sound of the letter 'A' naming itself; only choose the word where that sound is clearly heard.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: rain. In the word 'rain', the letters 'ai' work together to create the long 'a' sound (/eɪ/).","incorrect":[{"choice":"said","category":"irregular vowel sound","reason":"Although 'said' contains the letters 'ai', they make a short 'e' sound (/ɛ/) instead of the long 'a' sound."},{"choice":"plaid","category":"irregular vowel sound","reason":"In the word 'plaid', the 'ai' spelling makes a short 'a' sound (/æ/), which is not a long 'a' sound."},"",{"choice":"captain","category":"vowel team reduction","reason":"In 'captain', the 'ai' is part of an unstressed syllable and makes a short 'i' or 'uh' sound, not the clear long 'a' sound heard in 'rain'."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":136,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0137","version":3,"contentHash":"sha256:3270d53fe90f236a4ed5ebe0e8e9eaca04a115030132ce0166f8f636321ca203","question":"Grade 5 Easy: Choose the best answer. Which word has an r-controlled vowel?","choices":["bride","bread","brush","bird"],"correct":3,"studyAid":{"definition":"An r-controlled vowel happens when the letter 'r' follows a vowel and changes how that vowel sounds. The 'r' essentially 'steals' the vowel sound to make a new one.","example":"star (ar), fern (er), bird (ir), corn (or), fur (ur)","strategyClue":"Say each word out loud slowly. Listen for a vowel that sounds like it has been 'muffled' or changed into an 'er' sound by the letter 'r' immediately following it.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: bird. An r-controlled vowel occurs when a vowel is followed by an 'r' that changes its sound. In 'bird', the 'i' is controlled by the 'r', creating the 'er' sound.","incorrect":[{"choice":"bride","category":"long vowel sound","reason":"In 'bride', the 'i' makes a long vowel sound (like in 'kite'), not an r-controlled sound. The 'r' here is part of a consonant blend (br) rather than controlling the vowel."},{"choice":"bread","category":"vowel team","reason":"In 'bread', the letters 'ea' work together as a vowel team to make a short 'e' sound. The 'r' does not change the vowel sound here."},{"choice":"brush","category":"short vowel sound","reason":"In 'brush', the 'u' makes a short vowel sound. Similar to 'bride', the 'r' is part of the starting blend and does not control the vowel."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":137,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0138","version":3,"contentHash":"sha256:dba8b7625662a7c9804637cc9ff4e10d312bdcf7a14e82f34039cc3330df4c9d","question":"Grade 5 Easy: Choose the best answer. Which word contains a silent letter?","choices":["knock","rock","sock","lock"],"correct":0,"studyAid":{"definition":"A silent letter is a letter in a word that does not correspond to any sound in the word's pronunciation.","example":"knee (silent k), write (silent w), thumb (silent b)","strategyClue":"Say each word slowly and listen for the sound of every single letter; identify the word where the first letter is completely ignored in the sound.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: knock. The letter 'k' at the beginning of 'knock' is silent because it is not pronounced when you say the word aloud.","incorrect":["",{"choice":"rock","category":"pronounced consonants","reason":"Every letter in 'rock' is pronounced. You can clearly hear the 'r', 'o', 'c', and 'k' sounds when saying the word."},{"choice":"sock","category":"pronounced consonants","reason":"All the letters in 'sock' contribute to its sound. There are no hidden or silent letters here."},{"choice":"lock","category":"pronounced consonants","reason":"In 'lock', the 'l', 'o', 'c', and 'k' are all heard. It does not contain any silent letters."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":138,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0139","version":3,"contentHash":"sha256:f2e04c1a6212df4c9b31e3fa371ec1da09fcca34e61dd860b930c999308217ed","question":"Grade 5 Easy: Choose the best answer. Which spelling is correct?","choices":["becuase","because","becaus","beacuse"],"correct":1,"studyAid":{"definition":"The word 'because' is a conjunction used to show cause or reason, and it follows a specific, fixed order of letters.","example":"Correct: I ate because I was hungry. Incorrect: I ate becaus I was hungry.","strategyClue":"Break the word into syllables (be-cause) and focus on the middle section, visualizing the order of the letters 'a' and 'u' to verify the sequence.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: because. The word is spelled with an 'e-a-u' sequence in the middle. Remembering the mnemonic 'Big Elephants Can Always Understand Small Elephants' is a helpful way to recall the spelling of 'because'.","incorrect":[{"choice":"becuase","category":"vowel sequence error","reason":"This spelling incorrectly places the 'u' before the 'a'. Ensure you follow the standard sequence: 'b-e-c-a-u-s-e'."},"",{"choice":"becaus","category":"missing final letter","reason":"This word is missing the final 'e'. All instances of this conjunction must end with the letter 'e'."},{"choice":"beacuse","category":"letter transposition error","reason":"This spelling swaps the 'u' and the 'a'. In the correct spelling, the 'a' comes before the 'u'."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":139,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0140","version":3,"contentHash":"sha256:a18e8028c13f69ad5bd6c16405488eaf9d860e938e7bb6c21d4f45983c4c9c09","question":"Grade 5 Easy: Choose the best answer. The root photo means light. What does photograph most nearly mean?","choices":["a person who writes","a sound made underground","a picture made with light","a kind of water"],"correct":2,"studyAid":{"definition":"A root word is the base part of a word that carries its main meaning. Knowing the meaning of roots, like 'photo' (light), helps you define new words.","example":"Photosynthesis (light + putting together), Photocopy (light + copy), Photograph (light + drawing).","strategyClue":"Look at the beginning of the word to find the root. Focus on what 'photo' stands for and eliminate any options that don't describe that concept.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: a picture made with light. Since the root word 'photo' means light and the suffix '-graph' refers to writing or recording, 'photograph' literally means 'light writing' or a picture captured using light.","incorrect":[{"choice":"a person who writes","category":"incorrect suffix meaning","reason":"This definition describes an 'author' or a 'writer', but 'photograph' refers to the object or image created, not the person doing the action."},{"choice":"a sound made underground","category":"incorrect root interpretation","reason":"This does not relate to the root 'photo' (light). Words containing 'photo' will always relate to light, not sound or location."},"",{"choice":"a kind of water","category":"incorrect root interpretation","reason":"The root 'photo' never refers to water. If a word relates to water, it usually contains roots like 'aqua' or 'hydro'."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":140,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0141","version":3,"contentHash":"sha256:d773734e8fa060e6c49ec45c4c415f119a2cceae60da9fb9d83b362d96fa6db6","question":"Grade 5 Easy: Choose the best answer. The root port means carry. What does portable mean?","choices":["not visible","full of light","against water","able to be carried"],"correct":3,"studyAid":{"definition":"A suffix is a word part added to the end of a base word that changes its meaning, such as '-able' meaning 'capable of'.","example":"washable (able to be washed), breakable (able to be broken), portable (able to be carried).","strategyClue":"Break the word into two pieces: the root and the ending. Think about what the root word does and how the suffix changes that action into a description.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: able to be carried. The suffix '-able' means 'able to be' or 'capable of,' so when combined with the root 'port' (carry), it means able to be carried.","incorrect":[{"choice":"not visible","category":"incorrect suffix meaning","reason":"This definition implies a meaning related to vision or invisibility, which doesn't match the root 'port' meaning 'carry'."},{"choice":"full of light","category":"incorrect root interpretation","reason":"This describes something luminous, but 'port' is specifically about movement or carrying, not light."},{"choice":"against water","category":"confusing prefix/root","reason":"This sounds like the prefix 'anti-' which means against, but the word is 'portable', which focuses on the root 'port' meaning carry."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":141,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0142","version":3,"contentHash":"sha256:5229dd332cf9866fd7463f1a73d919a9366bb33a00500e0247d6ff7fcd8f4e95","question":"Grade 5 Easy: Choose the best answer. In \"The bat flew at dusk,\" what does bat mean?","choices":["a flying mammal","a stick used in baseball","to hit something","a folded paper"],"correct":0,"studyAid":{"definition":"Words with multiple meanings are called homonyms; you must look at the rest of the sentence to see which meaning fits.","example":"The bat (animal) flew away. He swung the bat (baseball) at the ball.","strategyClue":"Look at the other words in the sentence, especially the verb. If the noun is doing an action like 'flying,' choose the definition that is capable of doing that action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: a flying mammal. In this sentence, 'bat' refers to the nocturnal animal that flies at night, which fits the context of 'dusk'.","incorrect":["",{"choice":"a stick used in baseball","category":"multiple meaning word","reason":"While a baseball bat is a real thing, it does not make sense for a baseball stick to be flying around at dusk."},{"choice":"to hit something","category":"incorrect verb usage","reason":"The word 'bat' can be an action, but in this sentence, it is the subject performing the action 'flew', so it must be a noun."},{"choice":"a folded paper","category":"misunderstood definition","reason":"A folded paper does not fly on its own; this definition does not fit the context of the sentence."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":142,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0143","version":3,"contentHash":"sha256:1dd650e24e1124fcd43e823477b29a20788530808d697050b5da80b43ac8644a","question":"Grade 5 Easy: Choose the best answer. In \"Please park the car near the park,\" which word has two meanings?","choices":["please","park","near","car"],"correct":1,"studyAid":{"definition":"Homonyms are words that are spelled the same and sound the same, but have completely different meanings.","example":"Bat (a sports club vs. a flying animal), Bank (a place for money vs. the side of a river), Match (to pair things vs. a small stick used for fire).","strategyClue":"Look for the word that could fit into two very different types of sentences—one where you are doing an action, and one where you are pointing to a thing or place.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: park. The word 'park' is a homonym because it has two distinct meanings: it is both a verb meaning to leave a vehicle in a spot, and a noun referring to a public area with grass or trees.","incorrect":[{"choice":"please","category":"politeness marker","reason":"The word 'please' is used to make a request polite. It only has one primary meaning related to expressing courtesy."},"",{"choice":"near","category":"prepositional meaning","reason":"The word 'near' acts as a preposition showing distance. It does not have a secondary, unrelated meaning in this context."},{"choice":"car","category":"concrete noun","reason":"The word 'car' is a noun referring to a motor vehicle. It does not have multiple, common definitions that change based on how it is used in a sentence."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":143,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0144","version":3,"contentHash":"sha256:0e28599b58969a5e6532a7cb34e529781eb82279bd8cfb8baefce635f7c1d7d3","question":"Grade 5 Easy: Choose the best answer. Which word has the strongest meaning?","choices":["moved","walked","sprinted","went"],"correct":2,"studyAid":{"definition":"Stronger verbs create a clearer, more exciting picture in the reader's mind by showing exactly how an action is performed.","example":"Weak: He walked fast. Strong: He sprinted. Weak: She talked. Strong: She shouted.","strategyClue":"Imagine the action being performed at different speeds or energy levels. Pick the word that helps you visualize the most intense version of the movement.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: sprinted. The word 'sprinted' is the strongest choice because it specifically describes running at full speed, whereas the other options are more general or slower.","incorrect":[{"choice":"moved","category":"vague verb","reason":"'Moved' is a very general word. It does not tell the reader how fast the person was going, making it much weaker than 'sprinted'."},{"choice":"walked","category":"slow action verb","reason":"'Walked' describes a slow or steady pace. It is the opposite of 'sprinted' and does not show high energy or speed."},"",{"choice":"went","category":"vague action word","reason":"'Went' is a weak verb that lacks detail. It does not describe how the action was performed, unlike 'sprinted' which clearly defines the speed."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":144,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0145","version":3,"contentHash":"sha256:53319e78d5f746a57602590b7169860e3eead877a7c89f3612f9d5a12bd18c88","question":"Grade 5 Easy: Choose the best answer. Which word is gentler than furious?","choices":["explosive","enraged","livid","upset"],"correct":3,"studyAid":{"definition":"Synonyms are words that have similar meanings, but they can vary in their intensity or strength.","example":"Annoyed (mild) vs. Furious (extreme); Happy (mild) vs. Ecstatic (extreme); Tired (mild) vs. Exhausted (extreme)","strategyClue":"Think about the level of heat or energy behind each word. Rank the options from 'cool/mild' to 'very hot/intense' and pick the one that represents the lowest level of anger.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: upset. The word 'upset' describes a mild state of agitation or unhappiness, whereas 'furious' describes an extreme state of anger.","incorrect":[{"choice":"explosive","category":"synonym intensity","reason":"The word 'explosive' implies an intense or sudden outburst, which is equal to or even stronger than being furious."},{"choice":"enraged","category":"synonym intensity","reason":"'Enraged' means being filled with intense rage, making it a direct synonym for 'furious' rather than a gentler alternative."},{"choice":"livid","category":"synonym intensity","reason":"'Livid' is a strong word that means furiously angry, so it is just as intense as the word 'furious'."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":145,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0146","version":3,"contentHash":"sha256:e968a0b5ce7b9f8aaa63d4737c73d3be7921ae879a3d07cf5722940e8616df05","question":"Grade 5 Easy: Choose the best answer. How many syllables are in computer?","choices":["three","one","two","four"],"correct":0,"studyAid":{"definition":"Syllables are the sound beats in a word. Every syllable must contain at least one vowel sound.","example":"cat (1), hap-py (2), com-pu-ter (3), el-e-phant (3)","strategyClue":"Place your hand under your chin and say the word slowly. Count how many times your chin drops to touch your hand; each drop is one syllable.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: three. To find the syllables, clap out the beats as you say the word: com-pu-ter. There are three distinct parts to the word.","incorrect":["",{"choice":"one","category":"syllable counting error","reason":"If you say 'computer' very fast, it might sound like one sound, but it is actually a longer word with three distinct parts."},{"choice":"two","category":"syllable counting error","reason":"This word has three syllables, not two. Try breaking it down into 'com', 'pu', and 'ter' to hear the three beats."},{"choice":"four","category":"syllable counting error","reason":"There are only three vowel sounds in 'computer'. If you counted four, you might be adding an extra sound that isn't in the word."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":146,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0147","version":3,"contentHash":"sha256:97e0e3e4e2dbf0f01d7f5976486032996864b7323fc473507b7319a7ce3bd0b1","question":"Grade 5 Easy: Choose the best answer. Which word has a closed first syllable?","choices":["paper","rabbit","tiger","music"],"correct":1,"studyAid":{"definition":"A closed syllable is a syllable that ends in at least one consonant after one vowel. The vowel in a closed syllable is usually short.","example":"Closed: cat (ends in t), napkin (nap-kin, ends in p). Open: go (ends in o), robot (ro-bot, ends in o).","strategyClue":"Divide the word into its two syllables, then look at the very last letter of the first syllable. If it is a consonant, the syllable is closed.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: rabbit. A closed syllable ends in a consonant, which makes the vowel sound short. In 'rab-bit', the first syllable 'rab' ends in the consonant 'b', making the 'a' short.","incorrect":[{"choice":"paper","category":"open syllable error","reason":"The first syllable 'pa' ends in a vowel, making it an open syllable with a long 'a' sound. Closed syllables must end in a consonant."},"",{"choice":"tiger","category":"open syllable error","reason":"The first syllable 'ti' ends in a vowel. This creates an open syllable, which usually results in a long vowel sound instead of a short one."},{"choice":"music","category":"open syllable error","reason":"The first syllable 'mu' ends with a vowel sound. Because it is not \"closed\" by a consonant letter, it is an open syllable."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":147,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0148","version":3,"contentHash":"sha256:2e425dffbb15442d2ae0726347ea849f64f0800aaff99a796912d7ca126ee73a","question":"Grade 5 Easy: Choose the best answer. Which word uses ai to spell the long a sound?","choices":["said","plaid","rain","captain"],"correct":2,"studyAid":{"definition":"The 'ai' vowel team usually works together to make the long 'a' sound, which is the sound of the letter 'a' saying its own name.","example":"rain (long a), mail (long a), wait (long a)","strategyClue":"Say each word out loud slowly and listen for the sound of the letter 'a'. Only choose the word where the sound matches the name of the letter 'A'.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: rain. In the word 'rain', the 'a' and 'i' work together to create the long 'a' vowel sound, as in 'aid' or 'main'.","incorrect":[{"choice":"said","category":"irregular vowel sound","reason":"Although 'said' uses the letters 'ai', they create a short 'e' sound instead of the long 'a' sound."},{"choice":"plaid","category":"irregular vowel sound","reason":"The word 'plaid' uses 'ai', but it makes a short 'a' sound like in the word 'cat'."},"",{"choice":"captain","category":"unstressed vowel sound","reason":"In 'captain', the 'ai' combination appears in an unstressed syllable, creating a neutral or 'uh' sound rather than a clear long 'a'."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":148,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0149","version":3,"contentHash":"sha256:99ccb5603f9bee464627f666b864db906feb759e3591581070fc8dd8c5307c75","question":"Grade 5 Easy: Choose the best answer. Which word has an r-controlled vowel?","choices":["bride","bread","brush","bird"],"correct":3,"studyAid":{"definition":"An r-controlled vowel occurs when a vowel is followed by the letter 'r', causing the vowel to lose its normal short or long sound and take on a new sound.","example":"car (ar), her (er), bird (ir), corn (or), fur (ur)","strategyClue":"Look at the letter immediately following the vowel in each word. Identify which word has a vowel directly attached to the letter 'r'.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: bird. In this word, the vowel 'i' is followed by the letter 'r', which changes the vowel's sound to create the r-controlled 'er' sound.","incorrect":[{"choice":"bride","category":"long vowel sound","reason":"The 'i' in 'bride' is a long vowel sound caused by the silent 'e' at the end, not an r-controlled vowel."},{"choice":"bread","category":"vowel team","reason":"The 'ea' in 'bread' is a vowel team working together to make a short 'e' sound, not a vowel controlled by the letter 'r'."},{"choice":"brush","category":"short vowel sound","reason":"The 'u' in 'brush' makes a short 'u' sound because it is followed by consonants, but not specifically the letter 'r'."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":149,"skillIds":[],"standardIds":["RF/L.2-5"]}},{"id":"vocabulary-spelling-patterns-q0150","version":3,"contentHash":"sha256:43af73eb966c93ed5362eed719fc82404a4c1cdcd717151527d998b52757cf95","question":"Grade 5 Easy: Choose the best answer. Which word contains a silent letter?","choices":["knock","rock","sock","lock"],"correct":0,"studyAid":{"definition":"A silent letter is a letter that appears in a written word but is not heard when the word is spoken.","example":"knock (silent k), write (silent w), thumb (silent b), gnome (silent g)","strategyClue":"Say each word aloud slowly and distinctly. Listen carefully to see if you can hear every individual letter making its usual sound or if one seems to be hiding.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: knock. The 'k' at the beginning of 'knock' is a silent letter because it is not pronounced when you say the word out loud.","incorrect":["",{"choice":"rock","category":"pronounced consonant sounds","reason":"In the word 'rock', every letter makes a distinct sound. You can hear the 'r', 'o', 'c', and 'k' when you speak it."},{"choice":"sock","category":"pronounced consonant sounds","reason":"The word 'sock' does not have a silent letter. Each consonant, including the 's', 'c', and 'k', is clearly heard in the pronunciation."},{"choice":"lock","category":"pronounced consonant sounds","reason":"Every letter in 'lock' serves a purpose and contributes a sound. There are no letters here that remain silent while the word is spoken."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["spelling patterns","vowel teams","r-controlled vowels"],"standards":["RF/L.2-5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-spelling-patterns","sequence":150,"skillIds":[],"standardIds":["RF/L.2-5"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, with 15 exact-match questions for every supported grade and difficulty"}};
